/* Thermomix TM6 / TM7 : photo détourée (fond transparent) + calques animés par-dessus.
   option model : "tm6" (blanc, par défaut) ou "tm7" (noir).
   Calques : vitre sombre de l'écran (éteint), voyants (veille / mixage / chauffe), vapeur (chauffe, turbo) ;
   la machine vibre au mixage, plus fort en turbo. Éteint : filtre « sans vert » sur la photo (voyants de la photo éteints). */
const TMX_IMG = {
  tm6: "data:image/webp;base64,",
  tm7: "data:image/webp;base64,",
};
const TMX_GEO = {
  tm6: { x: 10, w: 99.9, scr: "29.6,95.8 73.6,104.3 69.3,132.1 23.6,121.6", leds: '<ellipse class="tmx-led" cx="34.8" cy="89.8" rx="4.5" ry="2.6"/><ellipse class="tmx-led" cx="71.8" cy="98.5" rx="4.5" ry="2.6"/>', steam: [61, 24.8] },
  tm7: { x: 11.8, w: 96.4, scr: "35.9,97.5 87.4,82.4 104.1,111.2 53.2,128.6", leds: '<ellipse class="tmx-led" cx="47.5" cy="69" rx="12.5" ry="3.8"/>', steam: [42.2, 19.7] },
};
const tmxModel = (c) => (String((c && c.model) || "").toLowerCase() === "tm7" ? "tm7" : "tm6");
SVG.thermomix = (c) => {
  const md = tmxModel(c), g = TMX_GEO[md], [sx, sy] = g.steam;
  return `<defs>${DEFS}
<!-- éteint : chaque canal = (rouge + bleu) / 2 × 0,85 → gris inchangés, voyants verts de la photo sombres -->
<filter id="ID-nogreen" color-interpolation-filters="sRGB"><feColorMatrix type="matrix" values=".425 0 .425 0 0  .425 0 .425 0 0  .425 0 .425 0 0  0 0 0 1 0"/></filter>
<linearGradient id="ID-glass" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3a4049"/><stop offset=".4" stop-color="#1d2126"/><stop offset="1" stop-color="#101215"/></linearGradient>
<linearGradient id="ID-sheen" x1="0" y1="0" x2="1" y2=".55"><stop offset=".18" stop-color="#fff" stop-opacity="0"/><stop offset=".26" stop-color="#fff" stop-opacity=".16"/><stop offset=".34" stop-color="#fff" stop-opacity=".05"/><stop offset=".4" stop-color="#fff" stop-opacity="0"/><stop offset=".62" stop-color="#fff" stop-opacity="0"/><stop offset=".68" stop-color="#fff" stop-opacity=".07"/><stop offset=".74" stop-color="#fff" stop-opacity="0"/></linearGradient>
<radialGradient id="ID-led"><stop offset="0" style="stop-color:var(--tmx-led1)"/><stop offset=".45" style="stop-color:var(--tmx-led2)" stop-opacity=".55"/><stop offset="1" style="stop-color:var(--tmx-led2)" stop-opacity="0"/></radialGradient>
<radialGradient id="ID-puff"><stop offset="0" stop-color="#fff"/><stop offset=".35" stop-color="#fff" stop-opacity=".65"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>
</defs>
<g class="tmx m-${md}">
<ellipse cx="60" cy="137" rx="44" ry="3.5" fill="url(#ID-shadow)"/>
<g class="tmx-body">
<g class="tmx-photo" filter="url(#ID-nogreen)"><image href="${TMX_IMG[md]}" x="${g.x}" y="12" width="${g.w}" height="128" preserveAspectRatio="none"/></g>
<g class="tmx-scr"><polygon points="${g.scr}" fill="url(#ID-glass)"/><polygon points="${g.scr}" fill="url(#ID-sheen)"/></g>
<g class="tmx-leds" fill="url(#ID-led)">${g.leds}</g>
</g>
<g class="tmx-steam" transform="translate(${sx} ${sy})" fill="url(#ID-puff)"><circle cx="-5" cy="0" r="5"/><circle cx="1" cy="0" r="5.5"/><circle cx="6" cy="0" r="4.5"/></g>
</g>`;
};
